# make transform fill single-cell holes when orthogonal neighbors of same color agree; otherwise clear singleton
p.write_text('def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == 0:
                continue
            neighbors = [grid[y][x] for y,x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0 <= y < h and 0 <= x < w]
            same = [x for x in neighbors if x == v]
            if len(same) == 0:
                # restore a hole when opposite sides match, else erase the isolated noise cell
                if r > 0 and r+1 < h and grid[r-1][c] == grid[r+1][c] and grid[r-1][c] != v:
                    out[r][c] = grid[r-1][c]
                elif c > 0 and c+1 < w and grid[r][c-1] == grid[r][c+1] and grid[r][c-1] != v:
                    out[r][c] = grid[r][c-1]
                else:
                    out[r][c] = 0
    return out
')
